// SYNC 4 – Zeiten (timeBuzzer -> Papierkram). timeBuzzer ist fuehrend.
const DRY_RUN = $('Testlauf (manuell)').isExecuted; // Start von Hand ueber "Testlauf (manuell)" = nur auswerten, keine Aenderungen. Aufruf durch andere Workflows = echter Lauf.
const MAX_DELETES = 10;  // Sicherung: mehr Loeschungen pro Lauf werden nicht automatisch ausgefuehrt

// Alle Seiten der Aktivitaeten einsammeln (Abruf mit Paginierung, 100 je Seite) und doppelte entfernen
const tbSeiten = $('TB – Aktivitäten abrufen').all();
const letzteSeite = tbSeiten.length ? (tbSeiten[tbSeiten.length - 1].json.activities || []) : null;
// Vollstaendigkeit: die letzte Seite muss weniger als 100 Eintraege haben, sonst wurde der Abruf vorzeitig begrenzt
if (!letzteSeite || letzteSeite.length >= 100) throw new Error('timeBuzzer-Aktivitäten unvollständig abgerufen (' + tbSeiten.length + ' Seiten). Sync abgebrochen, nichts geändert.');
const seen = new Set();
const activities = [];
for (const page of tbSeiten) {
  for (const a of (page.json.activities || [])) {
    if (!seen.has(String(a.id))) { seen.add(String(a.id)); activities.push(a); }
  }
}
const rawMappings = $('Mapping prüfen (DB)').all();
const mappings = rawMappings.map(item => item.json);

const rawProjects = $('PK – Projekte abrufen').all();
const propositionByProject = {};
for (const item of rawProjects) {
  const p = Array.isArray(item.json) ? item.json[0] : item.json;
  if (p && p.id && p.default_proposition) {
    propositionByProject[String(p.id)] = String(p.default_proposition.id);
  }
}

const existingTimeEntries = {};
const taskMappingsByCompositeKey = {};
const userMappings = {};

for (const m of mappings) {
  if (m.entity_type === 'time_entry') {
    existingTimeEntries[String(m.timebuzzer_tile_id)] = {
      pk_id: String(m.papierkram_id),
      hash: m.last_synced_hash || '',
      mapping_db_id: m.id
    };
  }
  if (m.entity_type === 'task') {
    try {
      const ed = typeof m.extra_data === 'string' ? JSON.parse(m.extra_data) : m.extra_data;
      if (ed && ed.compositeKey) {
        // aktive Aufgaben haben Vorrang vor archivierten mit gleichem Schluessel
        const prev = taskMappingsByCompositeKey[ed.compositeKey];
        if (!prev || m.status === 'active') {
          taskMappingsByCompositeKey[ed.compositeKey] = {
            pk_id: String(m.papierkram_id),
            pkProjectId: ed.pkProjectId ? String(ed.pkProjectId) : null
          };
        }
      }
    } catch(e) {}
  }
  if (m.entity_type === 'user') userMappings[String(m.timebuzzer_tile_id)] = String(m.papierkram_id);
}

// Relevant ist die Zeiterfassung ab dem Startdatum aus ally_einstellungen (zeiterfassung_ab, JJJJ-MM-TT, ueber "Mapping prüfen (DB)").
// Aeltere Aktivitaeten werden ignoriert. Leer = keine Untergrenze (Stefan 17.10.2026)
const abText = String((mappings[0] || {}).zeiterfassung_ab ?? '').trim();
const abTag = abText ? DateTime.fromISO(abText, { zone: 'Europe/Berlin' }) : null;
if (abText && (!/^\d{4}-\d{2}-\d{2}$/.test(abText) || !abTag.isValid)) throw new Error('Einstellung zeiterfassung_ab ist ungültig: ' + abText + ' (erwartet JJJJ-MM-TT). Sync abgebrochen, nichts geändert.');
const cutoffDate = abTag ? abTag.startOf('day').toJSDate() : null;
// Neu angelegt werden nur Zeiteintraege ab Beginn des Vormonats.
const createFrom = DateTime.now().setZone('Europe/Berlin').minus({ months: 1 }).startOf('month').toJSDate();
const activeActivityIds = new Set(activities.map(a => String(a.id)));
const results = [];

// Loeschen: Zeiteintrag existiert in Papierkram, Aktivitaet aber nicht mehr in timeBuzzer.
// Schutz 1: nur innerhalb des abgerufenen Bereichs (ID >= kleinste abgerufene ID).
// Schutz 2: bei mehr als MAX_DELETES Loeschungen wird nichts geloescht (Verdacht auf unvollstaendigen Abruf).
const fetchedIds = activities.map(a => Number(a.id)).filter(n => !isNaN(n));
const minFetchedId = fetchedIds.length ? Math.min(...fetchedIds) : Infinity;
const deletes = [];
for (const [activityId, entry] of Object.entries(existingTimeEntries)) {
  if (!activeActivityIds.has(activityId) && Number(activityId) >= minFetchedId) {
    deletes.push({ activityId, pk_id: entry.pk_id, mapping_db_id: entry.mapping_db_id, action: 'delete' });
  }
}
if (activities.length === 0 || deletes.length > MAX_DELETES) {
  for (const d of deletes) results.push({ json: { ...d, action: 'skip', reason: 'delete_blocked_safety', deleteCount: deletes.length } });
} else {
  for (const d of deletes) results.push({ json: d });
}

// Ortszeit Europe/Berlin - Sommer-/Winterzeit wird automatisch beruecksichtigt (Luxon).
const berlin = iso => DateTime.fromISO(iso, { zone: 'utc' }).setZone('Europe/Berlin').toFormat('yyyy-MM-dd HH:mm:ss');

for (const activity of activities) {
  const activityId = String(activity.id);
  if (cutoffDate && new Date(activity.startDate) < cutoffDate) {
    results.push({ json: { activityId, action: 'skip', reason: 'too_old' } });
    continue;
  }
  if (!activity.endDate) {
    results.push({ json: { activityId, action: 'skip', reason: 'running' } });
    continue;
  }

  const customerTileId = String(activity.tiles[0]);
  const projectTileId = String(activity.tiles[1]);
  const taskTileId = String(activity.tiles[2]);
  const compositeKey = `${customerTileId}|${projectTileId}|${taskTileId}`;

  const taskMapping = taskMappingsByCompositeKey[compositeKey];
  const tbUserId = String(activity.userId);
  const pkUserId = userMappings[tbUserId];

  if (!taskMapping) {
    results.push({ json: { activityId, action: 'skip', reason: 'no_task_mapping', compositeKey } });
    continue;
  }
  if (!pkUserId) {
    results.push({ json: { activityId, action: 'skip', reason: 'no_user_mapping', tbUserId } });
    continue;
  }

  const pkTaskId = taskMapping.pk_id;
  const pkProjectId = taskMapping.pkProjectId;
  const pkPropositionId = pkProjectId ? propositionByProject[pkProjectId] : null;

  const startedAt = berlin(activity.startDate);
  const endedAt = berlin(activity.endDate);
  const date = startedAt.split(' ')[0];
  const currentHash = `${activity.startDate}|${activity.endDate}|${activity.note || ''}|${compositeKey}`;
  const existing = existingTimeEntries[activityId];

  if (existing) {
    if (existing.hash === currentHash) {
      results.push({ json: { activityId, action: 'skip', reason: 'no_change' } });
    } else {
      results.push({ json: { activityId, pk_id: existing.pk_id, mapping_db_id: existing.mapping_db_id, pkTaskId, pkUserId, pkPropositionId, date, startedAt, endedAt, note: activity.note || '', current_hash: currentHash, action: 'update' } });
    }
    continue;
  }

  if (!pkPropositionId) {
    results.push({ json: { activityId, action: 'skip', reason: 'no_proposition', compositeKey, pkProjectId } });
    continue;
  }
  if (new Date(activity.startDate) < createFrom) {
    results.push({ json: { activityId, action: 'skip', reason: 'create_too_old', date } });
    continue;
  }
  results.push({ json: { activityId, pkTaskId, pkUserId, pkPropositionId, taskTileId, date, startedAt, endedAt, note: activity.note || '', current_hash: currentHash, action: 'create' } });
}

if (DRY_RUN) {
  return results.map(r => ({ json: { ...r.json, dry_action: r.json.action, orig_reason: r.json.reason || '', action: 'skip', reason: 'dry_run' } }));
}
return results;

return [{
  json: {
    pk_id: String($json.id),
    activity_id: $('Aktion verzweigen').item.json.activityId,
    current_hash: $('Aktion verzweigen').item.json.current_hash
  }
}];

return [{
  json: {
    current_hash: $('Aktion verzweigen').item.json.current_hash,
    mapping_db_id: $('Aktion verzweigen').item.json.mapping_db_id
  }
}];

// Nur Projekte aktiver Aufgaben abrufen (spart Papierkram-API-Aufrufe; Limit 10.000/Monat)
const rawMappings = $('Mapping prüfen (DB)').all();
const projectIds = new Set();
for (const item of rawMappings) {
  const m = item.json;
  if (m.entity_type === 'task' && m.status === 'active' && m.extra_data) {
    try {
      const ed = typeof m.extra_data === 'string' ? JSON.parse(m.extra_data) : m.extra_data;
      if (ed.pkProjectId) projectIds.add(ed.pkProjectId);
    } catch(e) {}
  }
}
return [...projectIds].map(id => ({ json: { pkProjectId: id } }));

// Hinweis im Ally-Chat statt Mail (Stefan 17.10.2026): eine Nachricht je Admin
const pk = $('Aktion verzweigen').item.json.pk_id;
const b = $('PK – Löschung prüfen').item.json.body || {};
const start = b.started_at || '-';
const abgerechnet = b.invoice_id ? 'ja (Rechnungs-ID ' + b.invoice_id + ')' : 'nein';
const esc = v => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = 'Abgleich Papierkram – timeBuzzer: Zeiteintrag konnte in Papierkram nicht gelöscht werden.\n\nEine Aktivität wurde in timeBuzzer gelöscht, der zugehörige Zeiteintrag in Papierkram ist aber noch vorhanden.\n\nPapierkram-Zeiteintrag: ' + pk + '\nStart: ' + start + '\nAbgerechnet: ' + abgerechnet + '\n\nBitte in Papierkram prüfen und ggf. von Hand korrigieren. Der Abgleich versucht es nicht erneut.';
const html = '<strong>Abgleich Papierkram – timeBuzzer:</strong> Zeiteintrag konnte in Papierkram nicht gelöscht werden.<br><br>Eine Aktivität wurde in timeBuzzer gelöscht, der zugehörige Zeiteintrag in Papierkram ist aber noch vorhanden.<br><br>Papierkram-Zeiteintrag: ' + esc(pk) + '<br>Start: ' + esc(start) + '<br>Abgerechnet: ' + esc(abgerechnet) + '<br><br>Bitte in Papierkram prüfen und ggf. von Hand korrigieren. Der Abgleich versucht es nicht erneut.';
return { json: { user_id: $json.matrix_user_id, text, html } };

// Fehler auf Deutsch (Stefan 24.10.2026, 12:20 „ja, Meldungen auf Deutsch“): technische Fehlertexte aus n8n bzw. von timeBuzzer/Papierkram werden für die
// Oberfläche in eine verständliche deutsche Meldung übersetzt. Der technische Text bleibt nur intern (n8n-Ausführung, Feld technik im Ergebnis).
// Gemeinsamer Code: Knoten „Fehler auf Deutsch“ in BERICHT 2 und SYNC 4, „Bericht-Ergebnis“ in ALLY 20, Anzeige in der Web-App (fehler_deutsch.ts gleich).
// dienst: 'timeBuzzer', 'Papierkram' oder leer (unbekannt). Eigene deutsche Meldungen (z. B. aus „Eingabe prüfen“) bleiben unverändert.
const FD_ENGLISCH = /(service unavailable|bad gateway|gateway time-?out|try again later|authorization failed|forbidden|check your credentials|too many requests|could not be found|timed? ?out|timeout|ETIMEDOUT|ECONNABORTED|ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|network error|internal server error|request failed|status code|NodeApiError|NodeOperationError|cannot read propert|is not defined|unexpected token|invalid json)/i;
function fdIstTechnisch(t) {
  const s = String(t || '').trim();
  if (!s) return false;
  if (FD_ENGLISCH.test(s)) return true;
  // reiner ASCII-Text mit typisch englischen Fehlerwörtern
  return /^[\x00-\x7F]*$/.test(s) && /\b(the|please|error|failed|unavailable|request|invalid|cannot|could not|unknown|denied|refused)\b/i.test(s);
}
function fdCode(e) {
  const o = e && typeof e === 'object' ? e : {};
  const roh = [o.httpCode, o.statusCode, o.message, o.description, typeof e === 'string' ? e : ''].map(x => String(x || '')).join(' ');
  const m = /\b([45][0-9][0-9])\b/.exec(String(o.httpCode || o.statusCode || '')) || /\b([45][0-9][0-9])\b/.exec(roh);
  return { code: m ? m[1] : '', roh };
}
function fehlerDeutsch(dienst, e) {
  const d = dienst || 'timeBuzzer oder Papierkram';
  const { code, roh } = fdCode(e);
  const spaeter = ' Bitte in ein paar Minuten erneut versuchen.';
  if (/^(500|502|503|504)$/.test(code) || /service unavailable|bad gateway|gateway time-?out|temporarily unavailable|internal server error/i.test(roh))
    return `${d} ist gerade nicht erreichbar.${spaeter}`;
  if (/^(401|403)$/.test(code) || /authorization failed|forbidden|check your credentials|unauthori[sz]ed/i.test(roh))
    return `Die Anmeldung bei ${d} ist fehlgeschlagen. Bitte den Zugang unter Einstellungen › Verbindungen prüfen.`;
  if (code === '429' || /too many requests/i.test(roh)) return `${d} meldet zu viele Anfragen.${spaeter}`;
  if (/ETIMEDOUT|ECONNABORTED|timed? ?out|timeout/i.test(roh)) return `${d} hat nicht rechtzeitig geantwortet.${spaeter}`;
  if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|network error/i.test(roh)) return `${d} ist gerade nicht erreichbar.${spaeter}`;
  if (code === '404' || /could not be found/i.test(roh)) return `${d} kennt einen angefragten Eintrag nicht (Fehler 404). Bitte prüfen, ob Kunde und Projekt dort noch bestehen.`;
  return `Bei ${d} ist ein Fehler aufgetreten${code ? ' (Fehler ' + code + ')' : ''}.${spaeter}`;
}

// Fehlerausgang eines lesenden Abrufs (nach 3 Versuchen): deutsche Meldung statt des englischen n8n-Texts; der Lauf bricht wie bisher ab.
const vorher = String($prevNode.name || '');
const dienst = /^TB/.test(vorher) ? 'timeBuzzer' : /^PK/.test(vorher) ? 'Papierkram' : '';
const j = $input.first().json || {};
throw new Error(fehlerDeutsch(dienst, j.error !== undefined ? j.error : j));
